<script>
import {api,put} from '../api'
export default{data:()=>({form:{firstName:'',lastName:'',phone:'',city:'',photoUrl:'',latitude:null,longitude:null,interestCategoryIds:[]},categories:[],busy:true,error:'',success:''}),async mounted(){try{const [p,c]=await Promise.all([api('/profile'),api('/catalog/categories')]);this.categories=c;this.form={...this.form,...p,interestCategoryIds:p.interests.map(x=>x.categoryId)}}catch(e){this.error=e.message}finally{this.busy=false}},methods:{async save(){this.busy=true;this.error='';this.success='';try{await put('/profile',this.form);this.success='Tus preferencias se guardaron correctamente.'}catch(e){this.error=e.message}finally{this.busy=false}}}}
</script>
<template><q-page class="container narrow"><div class="eyebrow">TU CUENTA</div><h1 class="page-heading">Tu perfil, tus planes</h1><p>Cuéntanos qué te interesa. La ubicación es opcional.</p><q-banner v-if="error" class="error" role="alert">{{error}}</q-banner><q-banner v-if="success" class="success" role="status">{{success}}</q-banner><q-form class="surface form-stack" @submit="save"><q-input outlined label="Nombres" v-model="form.firstName" maxlength="100" :rules="[v=>!!v.trim()||'Ingresa tus nombres']"/><q-input outlined label="Apellidos" v-model="form.lastName" maxlength="100" :rules="[v=>!!v.trim()||'Ingresa tus apellidos']"/><q-input outlined label="Teléfono" v-model="form.phone" maxlength="20"/><q-input outlined label="Ciudad (opcional)" v-model="form.city" maxlength="100"/><q-select outlined multiple use-chips label="Categorías de interés" v-model="form.interestCategoryIds" :options="categories" option-value="id" option-label="name" emit-value map-options/><q-btn type="submit" no-caps unelevated color="primary" label="Guardar preferencias" :loading="busy"/></q-form></q-page></template>
